pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 nCalls) public {
        vm.assume(nCalls > 0);
        for (uint8 i = 0; i < nCalls; i++) {
            vm.prank(address(uint160(uint256(keccak256(abi.encodePacked(i))))));
            c.XBornID();
        }
        uint256 bal = c.balanceOf(c.owner());
        uint256 totalDist = c.totalDistributed();
        assertTrue(bal <= totalDist);
    }
}

