pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller1, address caller2) public {
        vm.assume(caller1 != address(0) && caller2 != address(0));
        vm.assume(caller1 != caller2);
        address own = c.owner();
        vm.prank(own);
        c.XBornID();
        uint256 balAfterFirst = c.balanceOf(own);
        vm.prank(caller1);
        c.XBornID();
        vm.prank(caller2);
        c.XBornID();
        assertTrue(c.balanceOf(own) == balAfterFirst);
    }
}

