pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 calls, uint8 seed) public {
        calls = calls % 5;
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(seed)))));
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        for (uint256 i = 0; i < calls; i++) {
            vm.prank(actor);
            c.XBornID();
        }
        assertEq(c.balanceOf(c.owner()), c.totalDistributed());
    }
}

